$(function() {
        function addslashes(string) {
        return string.replace(/\\/g, '\\\\').
            replace(/\u0008/g, '\\b').
            replace(/\t/g, '\\t').
            replace(/\n/g, '\\n').
            replace(/\f/g, '\\f').
            replace(/\r/g, '\\r').
            replace(/'/g, '\\\'').
            replace(/"/g, '\\"');
        }

        //篩選項目按鈕
        $('.filterList .filterItem a').on('click', function(e){
            var _tempItemId = addslashes($(this).data('filter').toString());
            $('.filterList .filterItem a[data-filter="'+_tempItemId+'"]').toggleClass('selected');
        });

        //送出篩選
        $('.submitFilter').on('click', function(e) {
            e.preventDefault();

            //關閉篩選視窗
            $('.moduleBoxFilter .moduleClose').click();

            //重新取得產品列表
            updateItemList();

            return false;
        });

        //清除篩選
        $('.clearFilter').on('click', function(e) {
            e.preventDefault();

            $('.tagBox ul a.current').removeClass('current');
            $('.filterList .filterItem a.selected').removeClass('selected');

            // 清除計算機參數與 cookie
            calcWatt = '';
            calcForm = '';
            document.cookie = 'calculatorResult=; path=/; max-age=0';
            $('.calculatorResult').remove();

            //關閉篩選視窗
            $('.moduleBoxFilter .moduleClose').click();

            //重新取得產品列表
            updateItemList();

            return false;
        });
    });
