        $('#compare_list_html').append('<p class="text">尚未加入需要比較的商品</p>');
        return false;
    }

    for (var i=0;i<items.length;i++){
        const url = 'https://www.super-flower.com.tw/tw/products-detail/' +items[i].data_blink+'/';
        const imgDisplay = items[i].data_list_pic ? '' : 'hidden';
        $('#compare_list_html').append('<div class="cartItem">'+
        '<div class="Img '+imgDisplay+'"><a href="'+url+'"><img src="'+items[i].data_list_pic+'"></a></div>' +
        '<div class="Txt">'+
            '<p class="title"> <a href="'+url+'">'+items[i].data_title+'</a></p>'+
        '</div>'+
        '<button class="del" style="cursor:pointer" aria-label="刪除"><svg class="icon-garbage"><use xlink:href="#icon-garbage"></use></svg></button>'+
        '</div>');

        const currentItem = items[i];						        

        $('.del').last().on('click', function(){
            compare(currentItem.data_id);
        });
    }
}

function compare(id)
{
    if(!navigator.cookieEnabled) {
        $('#moduleCookie, .moduleMask').addClass('show');
        return false;
    }

    $.ajax({
        url:'https://www.super-flower.com.tw/tw/products/act/',
        type:"post",
        data:{'index_id':id,'act':5},
        cache:false,
        dataType:"text",
        success:function(result){
            var result = JSON.parse(result);
            if (result.status == 'error')
            {
                alert(result.msg.data_msg);
            }
            else if(result.status == 'add')
            {
                // $('[id="compare_btn_'+id+'"]').text('移除比較').addClass('bgSecond');
                $('[id="compare_btn_'+id+'"]').addClass('current');

                                    toasts.show('已加入比較', 'success');
                            }
            else if(result.status == 'remove')
            {
                // $('[id="compare_btn_'+id+'"]').text('加入比較').removeClass('bgSecond');
                $('[id="compare_btn_'+id+'"]').removeClass('current');

                                    toasts.show('已移除該項目', 'dark');
                            }

            $('#compare_list_html').html('');
            if(result.items !== null) 
            {
                printList(result.items);
                pdLen(result.items.length);
            }
        }
    });
}

