        // 僅在寬度大於 480px 時執行動畫
        mm.add("(min-width: 481px)", () => {
            // products
            const productTl = gsap.timeline({
                defaults: {
                    opacity: 0,
                    y: 20,
                    duration: 0.6,
                    ease: 'power2.out'
                },
                scrollTrigger: {
                    trigger: '.contentBox',
                    start: 'top 70%',
                    once: true,
                    onEnter: () => {
                        $('.contentBox').removeClass('beforeGsap');
                    }
                }
            })
            // .from('.contentBox .leftBox', {})
            .from('.contentBox .catalogItem', {
                stagger: 0.1
            });
        });
    })
